import pandas as pd

def solve(df_tickets: pd.DataFrame) -> pd.DataFrame:
    df = df_tickets[df_tickets['resolution_hours'].notna()].copy()
    df = df[['ticket_id', 'priority', 'resolution_hours']].copy()
    df['speed_tier'] = pd.cut(
        df['resolution_hours'],
        bins=[-0.01, 24, 72, float('inf')],
        labels=['fast', 'standard', 'slow']
    ).astype(str)
    return df.sort_values('ticket_id').reset_index(drop=True)

